import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Answers to Domain-Related Questions","description":"","frontmatter":{"title":"Answers to Domain-Related Questions"},"headers":[],"relativePath":"operations-knowledge-base/domain/answers-to-domain-related-questions.md","filePath":"operations-knowledge-base/domain/answers-to-domain-related-questions.md","lastUpdated":1794292919000}'),i={name:"operations-knowledge-base/domain/answers-to-domain-related-questions.md"};function s(r,e,l,d,u,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<p>1.How long after the domain is activated can I initiate a transfer?</p><ul><li>You can initiate a transfer after 60 days of activation.</li></ul><p>2.How to add DNS records?</p><ul><li>To add DNS records, log in to the control panel, navigate to the &quot;Domains&quot; section, click on &quot;My Domains&quot;, find the domain you want to manage, click the arrow icon at the end, select &quot;Manage Domain Name Servers&quot;, and then click on &quot;DNS Management&quot;. Add the DNS records in the required format.</li></ul><p>3.Can I change the registrant&#39;s email address, and how can I do it?</p><ul><li>Yes, you can change the registrant&#39;s email address. If your old email address is still functional and can receive emails, provide the new email address to us, and we will make the necessary changes. You will need to verify the change using the old email address. If the old email address is no longer accessible, completing the change will result in a 60-day lock on the domain, during which transfer operations cannot be performed.</li></ul><p>4.After domain resolution, it shows that I need to file for recordation.</p><ul><li>This issue arises when the domain is resolved to an IDC (Internet Data Center) service provider in mainland China without proper recordation. We are an international company, and our domain channels are international, not in mainland China. Only domains transferred to domain providers in mainland China can be recorded.</li></ul><p>5.Domain resolution is not successful.</p><ul><li>You need to ensure that the domain has been successfully verified before attempting to set up DNS resolution.</li></ul><p>6.Can I use Chinese characters when registering a domain?</p><ul><li>Chinese characters are not supported for domain registration, except for .CN domains.</li></ul><p>7.After purchasing a domain, how can I use the org email?</p><ul><li>You can retrieve the password and log in to the platform using your rak email through the following link:<a href="http://raksmart.china.myorderbox.com/customer" target="_blank" rel="noreferrer">http://raksmart.china.myorderbox.com/customer</a> After logging in, click on &quot;List Orders&quot; &gt; &quot;List/Search Orders&quot; &gt; &quot;Click the registered domain&quot; &gt; Go to the email section to activate the email. The free email service provides two email accounts with 100MB each. Domain forwarding can also be set up using the same steps, but there may be conflicts between enterprise email and domain forwarding. If you encounter any issues, you can submit a request in the support group, and we will manually enable the service. Usually, customers can use DNS resolution to point the domain to a server for website hosting, and the forwarding feature may not be necessary.</li></ul><p>8.How long does it take for a customer&#39;s domain purchase to be approved?</p><ul><li>After the customer receives a verification email and clicks on the verification link, the verification process usually takes up to 72 hours.</li></ul><p>9.Manually registered domains may not have DNS management enabled by default.</p><ul><li>During the domain configuration stage, make sure to select the option for DNS management.</li></ul><p>10.Can domain names be used for CDN CNAME resolution?</p><ul><li>Yes, you can add CNAME records for CDN resolution.</li></ul><p>11.Are there any limitations on domain names? If the customer&#39;s IP is blocked and they want to change the IP for resolution, is the domain locked?</p><ul><li>We do not have any limitations on domain names. However, when accessing websites, network firewalls may be in place. Just like how Google and Facebook are inaccessible in China, if the customer&#39;s IP is blocked, changing the IP should resolve the issue. If the domain itself is blocked, then the domain is essentially unusable.</li></ul><p>12.How long does it take for domain configuration changes to take effect?</p><ul><li>It may take approximately 1 to 72 hours for domain configuration changes to take full effect.</li></ul><p>13.How many domain names can be added to the enterprise email?</p><ul><li>1 person</li></ul>',26)])])}const p=a(i,[["render",s]]);export{h as __pageData,p as default};
